<?php
$start = !empty($event['start_at']) ? strtotime($event['start_at']) : false;
$end = !empty($event['end_at']) ? strtotime($event['end_at']) : false;
$where = implode(' · ', array_values(array_filter([
    trim((string)($event['venue'] ?? '')),
    trim((string)($event['city'] ?? '')),
    trim((string)($event['country'] ?? '')),
], static fn($value) => $value !== '')));
$ticketed = ($event['attendance_type'] ?? 'open') === 'ticketed';
$csrf = csrf_token();
?>
